const rawPayload = $json;
const payload = typeof rawPayload.body === 'string'
  ? JSON.parse(rawPayload.body || '{}')
  : (rawPayload.body ?? rawPayload);

function pick(...values) {
  return values.find(v => v !== undefined && v !== null && v !== '');
}

function transcriptToText(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) {
    return value.map(entry => {
      if (typeof entry === 'string') return entry;
      const speaker = pick(entry.role, entry.speaker, entry.name, 'Sprecher');
      const text = pick(entry.text, entry.message, entry.transcript, entry.content, '');
      return speaker + ': ' + text;
    }).join('\n');
  }
  return JSON.stringify(value, null, 2);
}

const message = payload.message ?? payload;
const __evtType = message.type ?? payload.type;
if (__evtType && __evtType !== 'end-of-call-report') { return []; }
const call = message.call ?? payload.call ?? {};
const analysis = message.analysis ?? payload.analysis ?? call.analysis ?? {};
const structured = analysis.structuredData ?? payload.structuredData ?? {};
const customer = call.customer ?? payload.customer ?? {};

const transcript = transcriptToText(pick(
  message.transcript,
  payload.transcript,
  analysis.transcript,
  call.transcript,
  message.artifact?.transcript,
  message.artifact?.messages,
  payload.messages,
  payload.recording?.transcript
));

const candidateName = pick(
  structured.candidate_name, structured.candidateName, structured.kandidat,
  structured.name, customer.name, payload.candidate_name, 'Nicht genannt'
);

const role = pick(
  structured.role, structured.rolle, structured.position,
  payload.role, payload.rolle, 'Nicht genannt'
);

const callId = pick(call.id, message.callId, payload.callId, 'unbekannt');
const callTime = pick(call.endedAt, call.ended_at, message.endedAt, new Date().toISOString());

const systemPrompt = [
  'Du bist ein erfahrener HR-Interview-Analyst. Analysiere das Gesprächstranskript eines Bewerber-Erstgesprächs.',
  '',
  'WICHTIGE REGELN:',
  '- Bewerte AUSSCHLIESSLICH auf Basis des Transkripts. Keine Spekulationen oder Ergänzungen.',
  '- Erfinde KEINE Informationen. Fehlende Angaben IMMER als "Nicht genannt" markieren.',
  '- Antworte NUR mit validem JSON ohne Markdown-Codeblöcke oder erklärende Texte.',
  '- Scores: 1=völlig ungeeignet, 5=durchschnittlich, 8=gut geeignet, 10=ausgezeichnet.',
  '- Empfehlung: weiterführen (Score 8-10) | prüfen (Score 5-7) | ablehnen (Score 1-4).',
  '',
  'Gib das Ergebnis EXAKT in diesem JSON-Format zurück (alle Felder erforderlich):',
  '{',
  '  "kandidat_name": "Name des Kandidaten oder Nicht genannt",',
  '  "zielrolle": "Beworbene Stelle oder Nicht genannt",',
  '  "kurzzusammenfassung": "2-3 prägnante Sätze zum Gesamteindruck",',
  '  "motivation": "Was der Kandidat zur Motivation und Wechselwunsch sagte, oder Nicht genannt",',
  '  "fachliche_eignung": "Konkrete Einschätzung der Qualifikationen auf Basis des Transkripts",',
  '  "kommunikation": "Einschätzung: klar/unklar, präzise/vage, sicher/unsicher, professionell",',
  '  "verfuegbarkeit": "Genannter Starttermin oder Kündigungsfrist, oder Nicht genannt",',
  '  "gehaltsvorstellung": "Genannte Gehaltsvorstellung in Euro, oder Nicht genannt",',
  '  "staerken": ["Konkrete belegbare Stärke 1", "Konkrete belegbare Stärke 2"],',
  '  "risiken": ["Konkretes Risiko oder Red Flag, oder Nicht erkannt"],',
  '  "fehlende_informationen": ["Fehlende wichtige Info 1"],',
  '  "empfehlung": "weiterführen",',
  '  "gesamt_score": 7,',
  '  "score_begruendung": "Sachliche Begründung, warum dieser Score vergeben wurde"',
  '}'
].join('\n');

const userMessage = [
  'Kandidat (aus Metadaten): ' + candidateName,
  'Zielrolle (aus Metadaten): ' + role,
  '',
  'Transkript:',
  transcript || 'Kein Transkript vorhanden. Alle inhaltlichen Felder mit "Nicht genannt" befüllen, gesamt_score auf 1 setzen, empfehlung auf "prüfen".'
].join('\n');

return [{
  json: {
    transcript,
    candidate_name: candidateName,
    role,
    call_id: callId,
    call_time: callTime,
    system_prompt: systemPrompt,
    user_message: userMessage,
    has_transcript: transcript.length > 50
  }
}];

const prev = $('Payload extrahieren').first().json;
const llmResponse = $json;

const rawContent = llmResponse?.choices?.[0]?.message?.content ?? '';

let parsed = {};
try {
  const __clean = rawContent.replace(/```json/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(__clean.slice(__clean.indexOf('{'), __clean.lastIndexOf('}') + 1));
} catch (e) {
  parsed = {
    kurzzusammenfassung: 'LLM-Antwort konnte nicht verarbeitet werden.',
    gesamt_score: 1,
    empfehlung: 'prüfen',
    fehlende_informationen: ['LLM-Parsing-Fehler: ' + String(e.message).slice(0, 100)],
    staerken: [],
    risiken: ['LLM-Antwort nicht verarbeitbar – bitte manuell prüfen'],
    score_begruendung: 'Fehler bei der automatischen Auswertung'
  };
}

function val(field, fallback) {
  const v = parsed[field];
  if (v !== undefined && v !== null && String(v).trim() !== '') return String(v);
  return fallback || 'Nicht genannt';
}

function arr(field) {
  const v = parsed[field];
  if (!v) return [];
  if (Array.isArray(v)) return v.filter(Boolean).map(String);
  if (typeof v === 'string') {
    return v.split('\n').map(s => s.replace(/^[-•*]\s*/, '').trim()).filter(Boolean);
  }
  return [String(v)];
}

const candidateName = val('kandidat_name', prev.candidate_name);
const role = val('zielrolle', prev.role);
const score = Math.max(1, Math.min(10, Math.round(Number(parsed.gesamt_score) || 5)));

const empfehlung = (() => {
  const e = val('empfehlung').toLowerCase();
  if (e.includes('weiter') || e.includes('pass') || e.includes('yes')) return 'weiterführen ✅';
  if (e.includes('ablehn') || e.includes('reject') || e.includes('nein') || e.includes('no')) return 'ablehnen ❌';
  return 'prüfen ⚠️';
})();

const staerken = arr('staerken');
const risiken = arr('risiken');
const fehlende = arr('fehlende_informationen');
const scoreEmoji = score >= 8 ? '🟢' : score >= 6 ? '🟡' : '🔴';

const slackLines = [
  '*Neues Bewerbergespräch ausgewertet*',
  '━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
  '*Kandidat:* ' + candidateName,
  '*Zielrolle:* ' + role,
  '*Zeitpunkt:* ' + prev.call_time,
  '*Call-ID:* ' + prev.call_id,
  '',
  '*Empfehlung:* ' + empfehlung,
  '*Score:* ' + scoreEmoji + ' ' + score + '/10',
  '',
  '*Kurzfazit:*',
  val('kurzzusammenfassung'),
  '',
  '*Motivation:*',
  val('motivation'),
  '',
  '*Fachliche Eignung:*',
  val('fachliche_eignung'),
  '',
  '*Kommunikationsstil:*',
  val('kommunikation'),
  '',
  '*Verfügbarkeit:* ' + val('verfuegbarkeit'),
  '*Gehaltsvorstellung:* ' + val('gehaltsvorstellung'),
  '',
  '*Stärken:*'
];

staerken.length
  ? staerken.forEach(s => slackLines.push('• ' + s))
  : slackLines.push('• Keine klaren Stärken erkannt');

slackLines.push('');
slackLines.push('*Risiken / Red Flags:*');
risiken.length
  ? risiken.forEach(r => slackLines.push('• ' + r))
  : slackLines.push('• Keine Risiken erkannt');

slackLines.push('');
slackLines.push('*Score-Begründung:*');
slackLines.push(val('score_begruendung'));

if (fehlende.length > 0) {
  slackLines.push('');
  slackLines.push('*Fehlende Informationen:*');
  fehlende.forEach(f => slackLines.push('• ' + f));
} else {
  slackLines.push('');
  slackLines.push('✓ Alle Kerninfos vorhanden');
}

slackLines.push('━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
slackLines.push('_KI-Vorauswertung (Llama 3.3 70B Instruct) – Bitte von HR validieren_');

return [{
  json: {
    candidate_name: candidateName,
    role,
    recommendation: empfehlung,
    score,
    summary: val('kurzzusammenfassung'),
    motivation: val('motivation'),
    fachliche_eignung: val('fachliche_eignung'),
    kommunikation: val('kommunikation'),
    verfuegbarkeit: val('verfuegbarkeit'),
    gehaltsvorstellung: val('gehaltsvorstellung'),
    staerken,
    risiken,
    fehlende_informationen: fehlende,
    score_begruendung: val('score_begruendung'),
    transcript: prev.transcript,
    call_id: prev.call_id,
    slack_text: slackLines.join('\n'),
    llm_raw: rawContent.slice(0, 500)
  }
}];
